  Future<bool> refreshConnectivity();

  /// Re-pull the layout + held orders + waitlist from the server NOW. Call
  /// on opening a floor surface and on a `floor.*` realtime event (a manager
  /// re-arranged the room in the dashboard, another till seated a party).
  /// Best-effort: offline leaves the mirrors as they are.
  Future<void> refreshFloor();

  Future<TillView?> refreshTill();

  /// The methods a refund of this sale may go back by, the sale's own when
  /// allowed, and whether the refund lands in a later shift than the sale.
  RefundMethodPlan refundMethodPlan({
    required String orderPaymentMethod,
    required String orderCreatedAt,
  });

  /// Refund money already taken, against a synced sale.
  ///
  /// NOT a void. Voiding a settled sale tells the books it never happened;
  /// this says it happened and some of the money went back. The till has
  /// been using a void to mean both, which is why no report can say what a
  /// month's refunds came to.
  ///
  /// Refused without an open shift — a refund is cash leaving a drawer.
  /// Queued and replayed like every other write, keyed so two partial
  /// refunds of one sale stay two events.
  Future<void> refundOrder({
    required String orderId,
    required PlatformInt64 amountMinor,
    required String method,
    required String reason,
    String? note,
  });

  /// Give a restored draft's claim back without changes (the "never mind"
  /// path out of a resume).
  Future<void> releaseDraft({required String id});

  /// Rename a parked draft in place — no restore, no re-park, nothing
  /// displaced. Held orders are device-local, so nothing is queued.
  Future<void> renameDraft({required String id, required String name});

  /// Render ONE item as a compact kitchen chit — no money, no logo, no
  /// totals. Pair with `send_to_printer`.
  Future<Uint8List> renderKitchenChit({
    required KitchenChit chit,
    required int width,
    required PrinterBrand brand,
  });

  /// Re-render a synced order as a receipt for reprint — same ESC/POS path as
  /// a fresh receipt. Offline-durable for any order seen online (cached).
  Future<Uint8List> renderOrderReceipt({
    required String orderId,
    required String storeName,
    required String currency,
    required int width,
    required PrinterBrand brand,
  });

  /// Render a placed order's receipt to printer bytes ready to stream to a
  /// thermal printer (rasterized 1-bit bitmap wrapped in the brand's raster
  /// protocol). Pair with `send_to_printer`.
  Future<Uint8List> renderReceipt({
    required ReceiptView receipt,
    required String storeName,
    required String currency,
    required int width,
    required PrinterBrand brand,
  });

  /// Render the shift report (Z-report) to printer bytes — rasterized like
  /// `render_receipt`. Pass the shift's `orders` to append the per-order
  /// breakdown (the expanded print); an empty list prints the summary only.
  /// Pair with `send_to_printer`.
  Future<Uint8List> renderTillReport({
    required TillReportView report,
    required String storeName,
    required String currency,
    required int width,
    required PrinterBrand brand,
    required List<OrderSummaryView> orders,
  });

  /// Re-verify local asset files and fetch what is missing.
  Future<AssetSyncView> repairAssets();

  /// Restore a draft into `table_id`'s cart (replaces its lines) and CLAIM
  /// it for this till. Errors when another till is editing it.
  Future<List<CartLineView>> restoreDraft({
    String? tableId,
    required String id,
  });

  /// Restore a HOST-supplied session blob (the one-time legacy keychain
  /// migration path). Writes through to the core's own store.
  Future<SessionSnapshot?> restoreSession({required List<int> blob});

  /// Re-hydrate the persisted session from the core's OWN store — the
  /// normal cold boot. `None` = signed out / fresh install.
  SessionSnapshot? restoreSessionCached();

  /// Requeue every dead command and try to send now.
  Future<void> retryOutbox();

  /// Retry one till's dead commands (a dead `open_till` holds only its till).
  Future<int> retryTillOutbox({required String tillId});

  /// Apply the reward rules to the asked picks (cap, balance, catalogue,
  /// bundles, shrunk or removed lines) and describe every line.
  RewardBoardView rewardBoard({
    required List<RewardLineInput> lines,
    required LoyaltyScanView scan,
    required List<RewardPick> picks,
  });

  /// The board's picks as the redemptions a checkout or settle sends.
  List<CheckoutRedemption> rewardRedemptions({
    required List<RewardLineInput> lines,
    required List<RewardPick> picks,
  });

  /// Whether a settled sale's tax was included, from its own figures.
  bool saleTaxInclusive({
    required PlatformInt64 subtotalMinor,
    required PlatformInt64 discountMinor,
    required PlatformInt64 serviceMinor,
    required PlatformInt64 deliveryMinor,
    required PlatformInt64 taxMinor,
    required PlatformInt64 totalMinor,
  });

  /// Search the branch's orders ACROSS shifts (history lookup) with optional
  /// filters (status / teller / payment method / from-to dates) + pagination
  /// (50/page, 1-based). Online-only.
  Future<OrderSearchPage> searchOrders({
    String? status,
    String? tellerName,
    String? paymentMethod,
    String? from,
    String? to,
    required int page,
  });

  /// The party arrived: mark the booking seated (optionally on another
  /// table). Optimistic-local + queued. Fire their ticket with `booking_id`
  /// to link it.
  Future<void> seatBooking({required String bookingId, String? tableId});

  /// SEAT a party: take the table, and nothing else.
  ///
  /// The floor's primary gesture. Takes the table on this device immediately
  /// and on every other one once it drains. It raises no kitchen ticket and
  /// opens no tab — sitting down is not a bill. The party's FIRST ROUND
  /// starts the tab and claims the table they are already at.
  /// `covers`: how many sat down, when the host counted — kept on every
  /// device and on the server's hold.
  Future<void> seatTable({required String tableId, int? covers});

  /// Best-effort raw-TCP send of pre-rendered ESC/POS bytes to a network
  /// (JetDirect / port 9100) thermal printer.
  Future<void> sendToPrinter({
    required String host,
    required int port,
    required List<int> bytes,
  });

  /// Bind the device to a branch (device setup). Clears the reconfigure flag.
  Future<void> setDeviceBranch({required String branchId, String? branchName});

  /// Set this device's managed code (Settings). Sanitized to short A-Z0-9; an
  /// empty/blank value is ignored (keeps the current code).
  void setDeviceCode({required String code});

  /// Persist a manual LAN hub-IP (`host` or `host:port`) in the device config and,
  /// if the relay is running, register it immediately. `None`/empty clears it.
  Future<void> setDeviceLanHub({String? hub});

  /// Set the device's receipt/chit printer (host:port + brand `"epson"`/`"star"`).
  /// `None` host clears it.
  Future<void> setDevicePrinter({String? host, int? port, String? brand});

  /// Bind the paired Bluetooth printer (MAC `address` + cached display `name`).
  /// `None` address clears it. The core stores the binding; the Flutter
  /// transport opens the socket.
  Future<void> setDevicePrinterBt({String? address, String? name});

  /// Pin the receipt raster width in dots (Settings paper-size toggle): 384 for
  /// a 58 mm roll, 576 for 80 mm. `None` clears it → the width falls back to the
  /// transport default (Bluetooth → 384, LAN → 576).
  Future<void> setDevicePrinterPaper({int? dots});

  /// Pick the printer transport — `"bluetooth"` (Classic SPP) or `"lan"`
  /// (raw-TCP, the default). Only the active transport's binding is used at
  /// print time; the other is retained so switching back is lossless.
  Future<void> setDevicePrinterTransport({required String kind});

  /// Bind the device's kitchen station (a KDS device). `None` clears it.
  Future<void> setDeviceStation({String? stationId});

  /// Set the branch's routing mode; `null` clears the override back to auto.
  /// Returns the effective mode the server resolved. Online-only.
  Future<String> setKitchenRoutingMode({String? mode});

  void setLocale({required String locale});

  /// SETTLE an open ticket into a paid order in the cashier's shift (a till
  /// action). Offline-first: the order is materialized server-side at replay,
  /// deduped on the ticket id. Returns true when still queued (offline). The
  /// cashier's settle-time discount/tip override the ticket's own.
  /// Settle a ticket into a paid order. Returns the ORDER ID once the settle
  /// has acked, so the caller can fetch its receipt and print — `None` while
  /// it is still queued offline, where no order exists yet.
  Future<String?> settleTicket({
    required String ticketId,
    required String tillId,
    required String paymentMethodId,
    PlatformInt64? amountTenderedMinor,
    PlatformInt64? tipMinor,
    String? tipPaymentMethodId,
    String? discountId,
    String? discountType,
    double? discountValue,
    String? loyaltyCustomerId,
    required List<CheckoutRedemption> loyaltyRedemptions,
    required List<CheckoutSplit> splits,
  });

  /// One-call sign-in: online first, offline PIN unlock fallback.
  Future<SessionSnapshot> signIn({required LoginRequest req});

  /// The leg a typed amount auto-fills (the only one still open), if any.
  CheckoutSplit? splitAutoFill({
    required PlatformInt64 dueMinor,
    required List<CheckoutSplit> legs,
    required List<String> typed,
    required String typedId,
  });

  /// "Rest here": the amount [target]'s leg takes so the split covers the due.
  PlatformInt64 splitRestHere({
    required PlatformInt64 dueMinor,
    required List<CheckoutSplit> legs,
    required String target,
  });

  /// Open the device's ONE session-level subscription. The core owns topic
  /// policy and alert decisions; `events` refreshes boards, `alerts`
  /// performs platform primitives. Idempotent while a subscription lives.
  Future<void> startRealtime({
    required RustStreamSink<RealtimeMessage> events,
    required RustStreamSink<AlertCommand> alerts,
  });

  /// Re-enter device setup (keeps the binding but forces the setup screen until
  /// `set_device_branch` confirms a — possibly new — branch).
  Future<void> startReconfigure();

  Future<PlatformInt64> suggestedOpeningCashMinor();

  /// Swap whatever sits on two tables (held orders and/or waiter tickets);
  /// one empty side = a move. Offline-safe (queued; the server arbitrates).
  ///
  /// Drains at once: an error means the server refused the move (its reason
  /// is the message) and the room was re-pulled; `Ok` means it landed or is
  /// queued offline.
  Future<void> swapFloorTables({
    required String tableA,
    required String tableB,
  });

  /// Resume a parked order in one call: park `from_table_id`'s cart (if
  /// asked), park anything already in the draft's own context, restore the
  /// draft there with its meta. Activates nothing: the view's `table_id`
  /// names the context the host should now show.
  Future<DraftSwitchView> switchToDraft({
    String? fromTableId,
    required String id,
    HeldParkInput? parkInHand,
    HeldParkInput? parkAtTarget,
  });

  /// Long-press: download everything again (unsent sales are kept).
  Future<SyncStatusView> syncFull();

  /// Incremental sync: drain the outbox, then pull.
  Future<SyncStatusView> syncNow();

  /// The till-open sync strip state.
  TillOpenSyncView syncOnTillOpenStatus();

  /// Sync health (one cheap local read; always succeeds offline).
  SyncStatusView syncStatus();

  /// A table's history and takings — ONLINE ONLY, never mirrored.
  ///
  /// Every other floor read is cached because a till has to keep selling
  /// with the network down. This one is a manager's question between
  /// services, and a stale copy would quietly answer a question about money
  /// with last week's numbers.
  Future<TableHistoryView> tableHistory({required String tableId});

  /// Price the tender in hand: the bar's total (tip included, split or not),
  /// the cash due, change / short, and what a split still has to allocate.
  TenderSummaryView tenderSummary({
    required PlatformInt64 dueMinor,
    required PlatformInt64 tipMinor,
    required bool tipIsCash,
    required PlatformInt64 tenderedMinor,
    required List<CheckoutSplit> splits,
    required bool duePriced,
    required bool addsOnTop,
  });

  /// A bill's lines a reward could name.
  List<RewardLineInput> ticketRewardLines({required String ticketId});

  /// The drawer arithmetic's cash-sales line, closed on the report's figure.
  PlatformInt64 tillCashSalesMinor({required TillReportView report});

  Future<TillReportView> tillReport();

  Future<TillReportView> tillReportFor({required String tillId});

  Future<TillStatsView> tillStats({required List<OrderSummaryView> orders});

  /// The tap on a reward line: one more unit, or clear it.
  List<RewardPick> toggleReward({
    required List<RewardLineInput> lines,
    required LoyaltyScanView scan,
    required List<RewardPick> picks,
    required int line,
  });

  /// Localized UI string for `key` (en/ar; falls back to en, then the key).
  String tr({required String key});

  /// Offline PIN unlock (argon2id against the cached credentials bundle).
  Future<SessionSnapshot> unlockOffline({
    required String name,
    required String pin,
    required String branchId,
  });

  /// Give a table back without a sale: they left before ordering, or the
  /// wrong table was tapped. Frees it outright — nobody ate, so there is
  /// nothing to bus.
  Future<void> unseatTable({required String tableId});

  /// Tear down the subscription (idempotent). Call before re-attaching
  /// sinks — including on Flutter hot restart.
  void unsubscribeRealtime();

  /// Check a selection against the item's group constraints (min/max/required).
  /// Empty result = valid; each entry is one violated group for inline display.
  /// Call before `cart_add_configured`.
  Future<List<GroupViolationView>> validateItemSelections({
    required String itemId,
    required List<AddonSelection> addons,
    required List<String> optionalFieldIds,
  });

  /// Core crate version.
  String version();

  /// Void a synced order (mistake/refund). Queues an idempotent `void_order`
  /// command and tries to send now; works offline. History reflects it
  /// immediately via the pending-void overlay.
  Future<void> voidOrder({
    required String orderId,
    required String reason,
    String? note,
    required bool restoreInventory,
  });

  /// VOID an open ticket (and pull its kitchen tickets off the KDS). Offline-first.
  Future<bool> voidTicket({required String ticketId, String? reason});

  /// Take ONE line off an open bill — "they sent the calamari back".
  ///
  /// Not a refund (nothing has been paid) and not a ticket void (the rest of
  /// the table's bill stands). Outbox-first and keyed on the line, so a
  /// retried drain cannot take the money off twice. Returns true while it is
  /// still queued; the line reads as voided on the bill either way.
  Future<bool> voidTicketLine({
    required String ticketId,
    required String itemId,
    String? reason,
  });
}
